  void ExportHeading(string text){var label=UI.Text(text,13);label.FontWeight=FontWeights.Medium;panel.Children.Add(label);}
  Button ExportChoice(string text,Action action){var b=UI.Button(text,action);b.Tag=text;b.Height=38;b.FontSize=12;b.Padding=new Thickness(3,6,3,6);return b;}
  void SelectExportChoice(Panel choices,string selected){foreach(Button b in choices.Children){bool active=(string)b.Tag==selected;b.Content=(string)b.Tag+(active?" ✓":"");UI.Role(b,Control.BackgroundProperty,active?"SelectedControl":"Well");UI.Role(b,Control.ForegroundProperty,active?"Ink":"Secondary");b.Effect=active?new DropShadowEffect {BlurRadius=5,ShadowDepth=1,Opacity=.04}:null;}}
  void UpdateExportSummary(){if(exportValues==null)return;var size=SceneLayout.OutputSize(doc,outputHeight);exportValues[0].Text="MP4 · "+(outputHdr?"H.265 HDR":outputCodec=="h265"?"H.265":"H.264");exportValues[1].Text=size[0]+" × "+size[1];exportValues[2].Text=outputFps+" fps";exportValues[3].Text=UI.Time(doc.Length);if(cancellation==null&&!done)status.Text="预计大小 · 约 "+Math.Max(.1,size[0]*(double)size[1]*outputFps*doc.Length*.16/8000000).ToString("0.0",CultureInfo.InvariantCulture)+" MB";}
  ExportOptions CurrentExportOptions(){return new ExportOptions {PresetName=presetName,Height=outputHeight,Fps=outputFps,Codec=outputCodec,Crf=outputCrf,Hdr=outputHdr,WriteChapters=writeChapters};}
  string ResolutionLabel(int height){return height==4320?"8K":height==2160?"4K":height+"p";}
  void ApplyExportPreset(string name){
   var p=ExportPresets.Find(name);
   if(p==null){presetName="自定义";return;}
   ApplyExportOptions(p);
  }
  void ApplyExportOptions(ExportOptions o){
   if(o==null)return;
   presetName=o.PresetName;outputHeight=o.Height;outputFps=o.Fps;outputCodec=o.Codec;outputCrf=o.Crf;outputHdr=o.Hdr;writeChapters=o.WriteChapters;
   if(resolutionChoices!=null)bump(resolutionChoices,ResolutionLabel(o.Height));
   if(rateChoices!=null)bump(rateChoices,o.Fps+" FPS");
   if(presetChoices!=null)bump(presetChoices,ExportPresets.Find(o.PresetName)!=null?o.PresetName:"自定义");
   if(o.Fps!=30&&o.Fps!=60&&o.Fps!=90){/* 自定义帧率不在三档里，分辨率行已同步，帧率行保持原样 */}
   UpdateSummary();
  }
  void RefreshSavedPresets(){
   if(savedPresetBox==null)return;
   object selected=savedPresetBox.SelectedItem;
   savedPresetBox.Items.Clear();
   foreach(string n in ExportPresetStore.List())savedPresetBox.Items.Add(n);
   if(selected!=null&&savedPresetBox.Items.Contains(selected))savedPresetBox.SelectedItem=selected;
  }
 }
